import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十一卦震 震为雷 震上震下","description":"周易 - 第五十一卦震 震为雷 震上震下","frontmatter":{"title":"第五十一卦震 震为雷 震上震下","description":"周易 - 第五十一卦震 震为雷 震上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/052.md","filePath":"zh/classics/zhouyi/052.md"}'),l={name:"zh/classics/zhouyi/052.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="震为雷" tabindex="-1">震为雷 <a class="header-anchor" href="#震为雷" aria-label="Permalink to “震为雷”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>震，亨。震来虩虩，恐致福也。笑言哑哑，后有则也。震惊百里，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>洊雷，震；君子以恐惧修身。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>震来虩虩，后笑言哑哑，吉。象曰：震来虩虩，恐致福也。笑言哑哑，后有则也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>震来厉，亿丧贝，跻于九陵，勿逐，七日得。象曰：震来厉，乘刚也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>震苏苏，震行无眚。象曰：震苏苏，位不当也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>震遂泥。象曰：震遂泥，未光也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>震往来厉，亿无丧，有事。象曰：震往来厉，危行也。其事在中，大无丧也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。象曰：震索索，未得中也。虽凶无咎，畏邻戒也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
